27	export type Result = { premium: number } | { payout: number; remainingCap: number };
28	
29	const PROCESSING_FEE = 5;
30	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
31	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	};
35	
36	const insuredItemsOf = (step: Step): Item[] => (step.op === "quote" ? step.items : []);
37	
38	const quoteFor = (items: Item[]): Result => {
39	  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
40	  return {
41	    premium: policyBase + policyBase * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE,
42	  };
43	};
44	
45	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
46	  results: scenario.steps.map((step) => quoteFor(insuredItemsOf(step))),
47	});
