const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const quoteFor = (items: Item[]): Result => {
  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  return {
    premium: policyBase + policyBase * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE,
  };
};

const resultFor = (step: Step): Result => quoteFor(step.items);

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map(resultFor),
});

const resultFor = (step: Step): Result => {
  if (step.op === "quote") return quoteFor(step.items);
  throw new Error(`unsupported step: ${step.op}`);
};
